import { fireEvent, render, screen } from "@testing-library/react";
import { describe, expect, test, vi } from "vitest";
import { BranchSelectorCompact } from "./branch-selector-compact";

vi.mock("react-i18next", () => ({
  useTranslation: () => ({
    t: (key: string) =>
      ({
        "assistant.branch.searchBranches": "Search branches",
        "assistant.branch.defaultBadge": "Default",
        "assistant.branch.noBranchesFound": "No branches found",
        "assistant.repo.newBranchAutoGenerated": "Create a new branch",
        "assistant.repo.noMatchingBranches": "No matching branches",
      })[key] ?? key,
  }),
}));

vi.mock("swr", () => ({
  default: () => ({
    data: { branches: ["main", "develop"], defaultBranch: "main" },
    isLoading: false,
    isValidating: false,
  }),
}));

describe("BranchSelectorCompact", () => {
  test("renders a compact footer trigger and keeps branch selection behavior", () => {
    const onChange = vi.fn();
    render(
      <BranchSelectorCompact
        owner="acme"
        repo="dashboard"
        value="main"
        isNewBranch={false}
        onChange={onChange}
        variant="sessionFooter"
      />,
    );

    const trigger = screen.getByRole("button", { name: /main/i });
    expect(trigger).toHaveClass("h-8", "w-auto", "border-0");

    fireEvent.click(trigger);
    fireEvent.click(screen.getByText("develop"));

    expect(onChange).toHaveBeenCalledWith("develop", false);
  });
});
